// SCH4-02 (high). Compare with... on PostgreSQL drops IDENTITY from a column: the table it creates
// has `id integer NOT NULL` with no default, so every INSERT that leaves id out fails there, and the
// second comparison says the schemas are the same.
// Steps: qa3s_src.t (id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY, v text), and u (id bigint
// GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY); qa3s_dst empty; Compare with... QA3 PG - qa3s_dst;
// run the script; INSERT INTO qa3s_dst.t (v) VALUES ('x').
// Expected: the target's id columns are identity columns (ALWAYS / BY DEFAULT as in the source) and
// the insert works. Actual: "id integer NOT NULL" in the script, is_identity = NO, the insert fails
// with a not-null violation.
// Code: crates/platypus-schema/src/lib.rs load() has no PostgreSQL identity read (Oracle has one,
// MySQL has auto_increment in `extra`); ddl.rs Ddl::column writes `extra` for Oracle and MySQL only.
import assert from "node:assert/strict";
import { DST, ENGINES, PLACES, SRC, needsEngines, openPath, psql, roundTrip, saveEngines, told } from "../qa3-schema.mjs";

export const skip = needsEngines("pg");

export function setup({ dir }) {
  ENGINES.pg.seed(dir, SRC, `CREATE TABLE S.t (id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY, v text);
CREATE TABLE S.u (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, v text);`);
  ENGINES.pg.seed(dir, DST, "");
  saveEngines(dir, ["pg"]);
}

export default async function (page) {
  const p = PLACES.pg;
  try {
    await openPath(page, [...p.chain, p.last]);
    const r = await roundTrip(page, p.chain, p.last, p.target, p.targetSchema);
    assert.ok(r.sql, told(r));
    assert.equal(r.runError, null, `the script fails: ${r.runError}\n${r.sql}`);
    assert.equal(
      psql(`SELECT string_agg(table_name || ':' || identity_generation, ',' ORDER BY table_name) FROM information_schema.columns WHERE table_schema = '${DST}' AND column_name = 'id' AND is_identity = 'YES'`),
      "t:ALWAYS,u:BY DEFAULT",
      `identity lost in:\n${r.sql}`,
    );
    psql(`INSERT INTO ${DST}.t (v) VALUES ('x')`);
  } finally {
    ENGINES.pg.drop(SRC);
    ENGINES.pg.drop(DST);
  }
}
